terraform {
  required_version = ">= 1.6"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  # `terraform init -backend=false` (used for local validate-only runs) skips
  # this regardless of what it says, so it's safe to always render it —
  # real applies and dry-run validates share one template either way.
  backend "s3" {
    bucket         = "mig-tfstate-408336117553"
    key            = "generated/app-pricing/terraform.tfstate"
    region         = "ap-south-1"
    dynamodb_table = "mig-tfstate-lock"
  }
}

provider "aws" {
  region = "ap-south-1"
}

module "app" {
  source           = "../../infra/terraform/modules/golden_app"
  name             = "app-pricing"
  port             = 8080
  instance_type    = "t3.micro"
  runtime          = "demo-server"
  env = {
    UPSTREAM_URL = "http://mig-edge-alb-1536629619.ap-south-1.elb.amazonaws.com/catalog/"
    REQUIRE_UPSTREAM = "1"
  }
  tags = {
    "owner" = "unknown-team"
    "cost-center" = "unknown"
    "data-class" = "internal"
  }
  target_group_arn   = "arn:aws:elasticloadbalancing:ap-south-1:408336117553:targetgroup/tg-app-pricing-target/ea86754954546453"
  vpc_id             = "vpc-06b381c1e65577891"
  private_subnet_ids = ["subnet-09486f771159b9ee2", "subnet-0e294b7c30225765f"]
  path_prefix        = "/pricing"
}
